pm.test("Status code is 200", () => {
  pm.response.to.have.status(200);
});

pm.test("Second step is required", () => {
  const body = pm.response.json();
  pm.expect(body.nextStep).to.exist;
  pm.expect(body).to.not.have.property("token");
});

pm.test("Responds in under 1000 ms", () => {
  pm.expect(pm.response.responseTime).to.be.below(1000);
});

// Pass data to the next request in the chain
pm.environment.set("pendingToken", pm.response.json().pendingToken);
